# -*- coding: utf-8 -*-
DAYS_2 = [
{"day":32,"book":"Acts","ref":"Acts 1-3","title":"Power from on High",
 "chapters":[
   ("Acts 1","Jesus ascends after promising the Holy Spirit's power for witness 'to the ends of the earth,' and the disciples choose Matthias to replace Judas among the Twelve."),
   ("Acts 2","At Pentecost the Spirit falls with wind and fire, enabling the disciples to speak in other languages; Peter preaches the first gospel sermon and 3,000 believe and are baptized in a single day."),
   ("Acts 3","Peter heals a lame beggar at the temple gate 'in the name of Jesus Christ' and preaches a second bold sermon calling Israel to repentance."),
 ],
 "themes":["The Holy Spirit's power, not human strategy, launched the church.","Bold, public gospel proclamation was the church's first instinct, not an afterthought."],
 "expositor":("stott","Stott observed that Pentecost reversed the confusion of Babel -- where languages once divided humanity, the Spirit now enabled the gospel to be understood across every language, foreshadowing a global, multi-ethnic church."),
 "reflect":"Peter, so recently fearful, preaches boldly at Pentecost. What might Spirit-given boldness look like for you this week?"},

{"day":33,"book":"Acts","ref":"Acts 4-6","title":"Bold Witness Amid Growing Pressure",
 "chapters":[
   ("Acts 4","Peter and John are arrested and threatened by the Sanhedrin but declare, 'we cannot stop speaking about what we have seen and heard,' and the believers respond to threats with united prayer for more boldness, not safety."),
   ("Acts 5","Ananias and Sapphira's deceitful giving is judged severely, underscoring God's holiness within the young church, while the apostles' bold witness and miracles continue despite arrest and flogging."),
   ("Acts 6","Growing practical needs lead to the appointment of seven Spirit-filled deacons (including Stephen) to serve widows, freeing the apostles for prayer and preaching, and the word of God continues to spread."),
 ],
 "themes":["Persecution provoked more prayer for boldness, not less witness.","God takes the integrity of His church's fellowship seriously."],
 "expositor":("macarthur","MacArthur points out that the believers' prayer after threats in Acts 4 asks not for the threat to be removed but for boldness to keep speaking -- a model of praying for courage to face hardship rather than only for the hardship's removal."),
 "reflect":"When facing pressure or opposition, do your prayers tend to ask more for escape, or for courage to remain faithful within it?"},

{"day":34,"book":"Acts","ref":"Acts 7-9","title":"Stephen's Martyrdom Sparks the Gospel's Spread",
 "chapters":[
   ("Acts 7","Stephen delivers a sweeping sermon tracing Israel's history of resisting God's messengers, and is stoned to death as the first Christian martyr, praying for his killers' forgiveness as he dies."),
   ("Acts 8","Persecution scatters believers from Jerusalem, spreading the gospel to Samaria through Philip, including the transformation of a sorcerer named Simon and an Ethiopian court official."),
   ("Acts 9","Saul, a zealous persecutor of the church, is dramatically converted on the road to Damascus and begins his transformation from persecutor to proclaimer of the very faith he once tried to destroy."),
 ],
 "themes":["God can turn even persecution into a means of gospel expansion.","No opponent of the gospel is beyond the reach of God's grace."],
 "expositor":("baucham","Baucham has noted that Saul's conversion stands as one of history's clearest evidences for the resurrection -- a hostile, well-educated eyewitness with every incentive to disprove Christianity instead became its most zealous advocate after encountering the risen Christ."),
 "reflect":"Stephen prayed for his killers as he died. Is there someone opposing you that you need to pray blessing over rather than resentment toward?"},

{"day":35,"book":"Acts","ref":"Acts 10-12","title":"The Gospel Breaks Its Ethnic Boundaries",
 "chapters":[
   ("Acts 10","God gives Peter a vision overturning his assumptions about ritual purity, leading him to preach to Cornelius, a Roman centurion, whose household receives the Holy Spirit -- proof the gospel is for Gentiles too."),
   ("Acts 11","Peter defends this decision to Jewish believers in Jerusalem, and the church at Antioch becomes the first place believers are called 'Christians.'"),
   ("Acts 12","Herod Agrippa kills James and imprisons Peter, who is miraculously freed by an angel in answer to the church's earnest prayer, while Herod later dies under God's judgment."),
 ],
 "themes":["The gospel was always intended to cross every ethnic and cultural line.","Earnest, persistent prayer moves God to act, even in impossible circumstances."],
 "expositor":("carson","Carson has emphasized that Peter's vision in Acts 10 wasn't primarily about food laws but about people -- teaching Peter (and the whole church after him) that no group of people is 'unclean' or outside the reach of God's welcome."),
 "reflect":"Is there a group of people you've subtly assumed are 'outside' the reach of the gospel, whom God might be calling you to welcome?"},

{"day":36,"book":"Acts","ref":"Acts 13-15","title":"To the Ends of the Earth, and a Council's Verdict",
 "chapters":[
   ("Acts 13","The church at Antioch commissions Paul and Barnabas for the first missionary journey; Paul preaches his first recorded sermon in Pisidian Antioch, turning to the Gentiles when many Jews reject the message."),
   ("Acts 14","Paul and Barnabas endure both idolatrous adoration (mistaken for gods at Lystra) and violent stoning within the same journey, yet continue strengthening new churches."),
   ("Acts 15","The Jerusalem Council settles the crucial question of whether Gentile converts must be circumcised and keep the Mosaic law, concluding they are saved by grace through faith alone, just like Jewish believers."),
 ],
 "themes":["Gospel mission inevitably faces both dramatic acceptance and dramatic opposition.","Salvation by grace through faith applies equally to every ethnic background."],
 "expositor":("bruce","F. F. Bruce regarded the Jerusalem Council's decision in Acts 15 as one of the most consequential in church history -- had it gone the other way, Christianity might have remained a minor Jewish sect rather than a faith genuinely open to the whole world."),
 "reflect":"Paul and Barnabas kept going after both adoration and violence in the same trip. What keeps you steady when circumstances swing between encouragement and hardship?"},

{"day":37,"book":"Acts","ref":"Acts 16-18","title":"Philippi, Athens, and Corinth",
 "chapters":[
   ("Acts 16","Paul's team is redirected by the Spirit to Macedonia, where Lydia and a jailer are converted in Philippi after Paul and Silas, though beaten and imprisoned, worship God at midnight and are miraculously freed."),
   ("Acts 17","In Athens, Paul reasons with philosophers at the Areopagus, quoting their own poets and pointing them from an altar 'to an unknown god' to the risen Christ."),
   ("Acts 18","Paul plants a church in Corinth over eighteen months, meets Priscilla and Aquila, and continues his second missionary journey, later disputing publicly in Ephesus."),
 ],
 "themes":["Worship and witness can flourish even in unjust suffering.","Effective evangelism engages a culture's own language and assumptions to point toward Christ."],
 "expositor":("keller","Keller frequently used Paul's Areopagus speech as a model for cultural engagement -- Paul respectfully builds a bridge from the Athenians' own religious instincts and poetry to the gospel, rather than simply condemning their culture outright."),
 "reflect":"What common ground in your culture or a friend's worldview might serve as a bridge toward a gospel conversation, the way Paul used the Athenians' own altar and poets?"},

{"day":38,"book":"Acts","ref":"Acts 19-21","title":"Ephesus Ablaze, Paul Presses Toward Jerusalem",
 "chapters":[
   ("Acts 19","In Ephesus, extraordinary miracles occur through Paul, new believers publicly burn valuable scrolls of sorcery, and a riot erupts among silversmiths whose idol-making trade is threatened by the gospel's spread."),
   ("Acts 20","Paul's farewell to the Ephesian elders reveals his pastoral heart, warning of coming false teachers and reminding them, 'it is more blessed to give than to receive.'"),
   ("Acts 21","Despite repeated prophetic warnings of danger, Paul resolves to go to Jerusalem 'ready to die for the name of the Lord Jesus,' where he is soon arrested in the temple."),
 ],
 "themes":["Genuine conversion produces costly, visible change, not just private belief.","Faithful mission sometimes requires proceeding despite clear warnings of danger."],
 "expositor":("wiersbe","Wiersbe highlighted that the Ephesians' public burning of their magic scrolls -- a small fortune destroyed rather than sold -- shows that real repentance is willing to take a costly, decisive, public stand against one's former life."),
 "reflect":"Is there something costly you know you should decisively let go of, rather than merely try to manage or hide?"},

{"day":39,"book":"Acts","ref":"Acts 22-24","title":"Paul on Trial",
 "chapters":[
   ("Acts 22","Paul recounts his dramatic conversion testimony to a hostile Jerusalem crowd, provoking renewed uproar when he mentions his calling to the Gentiles."),
   ("Acts 23","Paul cleverly (and honestly) divides the Sanhedrin over resurrection doctrine, survives an assassination plot, and is transferred under heavy guard to the governor Felix in Caesarea."),
   ("Acts 24","Paul defends himself before Felix, speaking so candidly about righteousness and judgment that the governor becomes afraid, yet delays a decision for two self-serving years."),
 ],
 "themes":["Personal testimony remains a powerful, simple form of gospel witness.","Truth can unsettle even powerful people who still refuse to act on it."],
 "expositor":("ryrie","Ryrie observed that Paul's repeated retelling of his own conversion story throughout Acts models how every believer's personal testimony -- however ordinary -- can function as clear, compelling evidence of God's work, regardless of one's platform or credentials."),
 "reflect":"How comfortable are you telling your own story of coming to faith, the way Paul retold his so readily?"},

{"day":40,"book":"Acts","ref":"Acts 25-26","title":"Before Festus and Agrippa",
 "chapters":[
   ("Acts 25","Paul, facing renewed plots against his life, exercises his right as a Roman citizen to appeal to Caesar, setting in motion his eventual journey to Rome."),
   ("Acts 26","Paul gives his most detailed defense yet before King Agrippa, recounting his conversion and mission so compellingly that Agrippa admits Paul has almost persuaded him to become a Christian."),
 ],
 "themes":["God can use legal and political systems to advance His purposes.","Compelling gospel witness can move even powerful listeners close to belief without guaranteeing their response."],
 "expositor":("rogers","Adrian Rogers often noted that Agrippa's response -- 'almost persuaded' -- represents one of Scripture's saddest phrases, since being nearly convinced of the truth and yet still walking away leaves a person no better off than total unbelief."),
 "reflect":"Is there any way you've been 'almost persuaded' by truth you know but haven't fully acted on?"},

{"day":41,"book":"Acts","ref":"Acts 27-28","title":"Shipwrecked, Yet Unstoppable",
 "chapters":[
   ("Acts 27","Paul's voyage to Rome is battered by a violent storm and ends in shipwreck, yet Paul's calm faith and an angel's assurance steady the entire ship's company, and all 276 aboard survive."),
   ("Acts 28","Shipwrecked on Malta, Paul survives a venomous snakebite and heals the sick, then finally arrives in Rome, where he preaches the kingdom of God boldly and unhindered even under house arrest."),
 ],
 "themes":["God's purposes can advance through, not just despite, disaster and hardship.","The gospel proved unstoppable even under Roman imprisonment, closing Acts on a note of open triumph."],
 "expositor":("henry","Matthew Henry noted that Luke deliberately ends Acts not with Paul's death but with him 'boldly and without hindrance' preaching in Rome -- a fitting close showing that no chain, storm, or empire could ultimately contain the advance of the gospel."),
 "reflect":"Acts ends open-ended, as if the story continues through us. What's one way you could carry that same unhindered gospel boldness into your own week?"},

{"day":42,"book":"Romans","ref":"Romans 1-3","title":"The Universal Need for Righteousness",
 "chapters":[
   ("Rom 1","Paul introduces the gospel as 'the power of God for salvation,' then argues that all humanity -- Gentile and Jew alike -- stands guilty for suppressing the truth of God evident in creation."),
   ("Rom 2","Paul turns to those who feel morally superior for possessing religious knowledge, showing that judgment is based on genuine obedience from the heart, not mere possession of God's law."),
   ("Rom 3","Paul concludes that 'no one is righteous' and 'all have sinned,' then unveils the solution: righteousness is credited to anyone -- Jew or Gentile -- who trusts in Christ's atoning sacrifice, apart from law-keeping."),
 ],
 "themes":["Every person, religious or not, is equally in need of God's grace.","Justification -- being declared righteous -- comes only through faith in Christ, not personal merit."],
 "expositor":("sproul","Sproul repeatedly emphasized Romans 3's teaching that justification is a legal declaration -- God credits Christ's righteousness to the believer's account -- not a gradual self-improvement process, which is exactly why grace, not performance, remains the only sure ground for confidence before God."),
 "reflect":"Do you tend to base your standing before God more on Christ's finished work, or on your own recent performance?"},

{"day":43,"book":"Romans","ref":"Romans 4-6","title":"Abraham's Faith, Adam's Fall, Union with Christ",
 "chapters":[
   ("Rom 4","Paul uses Abraham -- credited righteous by faith before circumcision even existed -- as proof that justification by faith was always God's plan, not a New Testament innovation."),
   ("Rom 5","Paul contrasts Adam's one act of disobedience, which brought sin and death to all, with Christ's one act of obedience, which brings grace and life to all who believe."),
   ("Rom 6","Paul insists that grace is never a license to keep sinning; believers have died to sin's rule with Christ and are to consider themselves genuinely 'alive to God' in a new pattern of life."),
 ],
 "themes":["Justification by faith is the consistent pattern of the whole Bible, not a late addition.","Grace transforms behavior; it never excuses ongoing sin as harmless."],
 "expositor":("stott","Stott stressed that Romans 6 answers a natural but wrong conclusion people draw from grace -- 'should we sin more so grace can increase?' -- with an emphatic no, because union with Christ's death and resurrection has fundamentally changed what believers are, not merely what rules they follow."),
 "reflect":"Is there an area where you've unconsciously treated grace as permission to stay stuck, rather than power to actually change?"},

{"day":44,"book":"Romans","ref":"Romans 7-9","title":"The Inner Struggle and the Spirit's Freedom",
 "chapters":[
   ("Rom 7","Paul candidly describes the ongoing struggle between wanting to do good and finding sin's pull still present, even in a genuine believer's life."),
   ("Rom 8","Paul declares 'no condemnation' for those in Christ, describes the Spirit's indwelling power and adoption as God's children, and affirms nothing can separate believers from God's love."),
   ("Rom 9","Paul grapples with Israel's unbelief despite their privileges, defending God's sovereign right to show mercy according to His own purposes."),
 ],
 "themes":["Ongoing struggle with sin doesn't disqualify genuine faith.","Nothing in all creation can separate a believer from God's love in Christ."],
 "expositor":("piper","Piper has often called Romans 8 the mountain peak of the entire Bible, arguing that its climactic promise -- nothing can separate us from the love of God in Christ Jesus -- is meant to become the settled, joy-producing confidence underneath a believer's whole life."),
 "reflect":"Which phrase from Romans 8 (no condemnation, adopted as a child, more than conquerors, nothing can separate) do you most need to rest in this week?"},

{"day":45,"book":"Romans","ref":"Romans 10-12","title":"Israel's Future, the Believer's Response",
 "chapters":[
   ("Rom 10","Paul insists that faith comes through hearing the message about Christ, expressing his deep longing for Israel's salvation and the necessity of gospel proclamation for anyone to believe."),
   ("Rom 11","Paul uses the image of an olive tree to explain that Gentile believers have been 'grafted in' among God's people, while affirming that God has not permanently rejected Israel."),
   ("Rom 12","Paul pivots from doctrine to practice, urging believers to offer themselves as 'living sacrifices,' to be transformed by renewed minds, and to exercise their varied spiritual gifts in genuine love."),
 ],
 "themes":["Gospel proclamation remains essential -- faith doesn't arise apart from hearing the message.","Sound doctrine should always lead to practical, sacrificial, Spirit-empowered living."],
 "expositor":("wright","N. T. Wright has noted that Romans 12's call to 'renew your mind' isn't abstract self-improvement, but the direct, practical outworking of everything Paul has argued theologically in chapters 1-11 -- doctrine deliberately reshaping daily conduct."),
 "reflect":"Romans 12:2 calls for a renewed mind rather than conformity to the world. What's one pattern of thinking you sense needs active renewal right now?"},

{"day":46,"book":"Romans","ref":"Romans 13-14","title":"Citizens of Two Kingdoms, Patient with Weaker Faith",
 "chapters":[
   ("Rom 13","Paul instructs believers to submit to governing authorities as instituted by God, while summarizing all specific commands under the single call to love one's neighbor."),
   ("Rom 14","Paul addresses disputes over disputable matters (like food and holy days) among believers of differing conviction, urging mutual acceptance and a refusal to judge or cause a weaker believer to stumble."),
 ],
 "themes":["Christian citizenship includes real, though not unlimited, respect for civil authority.","Charity toward differing convictions on secondary issues matters more than winning the argument."],
 "expositor":("carson","Carson has pointed out that Romans 14's principle of not causing a 'weaker' believer to stumble isn't about avoiding all disagreement, but about prioritizing another person's spiritual good over one's own liberty in matters Scripture leaves genuinely open."),
 "reflect":"Is there a 'disputable matter' where insisting on your own freedom might be costing someone else's spiritual good?"},

{"day":47,"book":"Romans","ref":"Romans 15-16","title":"Unity in Mission, Personal Greetings",
 "chapters":[
   ("Rom 15","Paul calls Jewish and Gentile believers to unity modeled on Christ's own example, and shares his ambitious mission plans to preach where Christ is not yet known, hoping for the Romans' partnership toward Spain."),
   ("Rom 16","Paul closes with an unusually long list of personal greetings, commending numerous named individuals -- including several women in significant ministry roles -- for their labor in the gospel."),
 ],
 "themes":["Gospel unity between different backgrounds was central to Paul's missionary vision.","The early church's ministry depended on many named, often overlooked, faithful individuals."],
 "expositor":("wiersbe","Wiersbe observed that Romans 16's long list of names -- ordinary people doing largely unrecorded work -- is a quiet reminder that God's kingdom advances chiefly through faithful, often unnoticed believers, not only through famous leaders like Paul."),
 "reflect":"Is there quiet, 'unnoticed' faithfulness in your own life or someone else's that deserves more thanks than it gets?"},

{"day":48,"book":"1 Corinthians","ref":"1 Corinthians 1-3","title":"The Wisdom of the Cross Against Worldly Wisdom",
 "chapters":[
   ("1 Cor 1","Paul confronts factional divisions in Corinth (some claiming loyalty to Paul, Apollos, or Cephas) and insists the cross -- foolish to Greek wisdom, offensive to Jewish expectation -- is actually the very wisdom and power of God."),
   ("1 Cor 2","Paul explains that spiritual truth is discerned only through the Holy Spirit, not human eloquence or philosophy, and that he deliberately preached in plain weakness so their faith would rest on God's power, not clever rhetoric."),
   ("1 Cor 3","Paul rebukes the Corinthians' spiritual immaturity shown in their quarreling, describing himself and Apollos as mere servants and warning that every believer's work will be tested by fire."),
 ],
 "themes":["The cross overturns worldly categories of wisdom and status.","Church unity matters more than loyalty to any single human leader or teacher."],
 "expositor":("barclay","Barclay noted that in a status-obsessed city like Corinth, aligning with a prestigious teacher was itself a badge of social standing, which is exactly why Paul insists all human teachers are merely servants and Christ alone deserves ultimate allegiance."),
 "reflect":"Is there a teacher, leader, or public figure whose approval or platform you've quietly elevated above simple allegiance to Christ?"},

{"day":49,"book":"1 Corinthians","ref":"1 Corinthians 4-6","title":"Church Discipline, Lawsuits, and Purity",
 "chapters":[
   ("1 Cor 4","Paul contrasts the apostles' suffering servanthood with the Corinthians' arrogant self-satisfaction, urging them to imitate his humble, sacrificial example."),
   ("1 Cor 5","Paul commands the church to remove an unrepentant member involved in blatant sexual immorality, insisting that genuine love sometimes requires firm, restorative church discipline rather than tolerance."),
   ("1 Cor 6","Paul rebukes believers for suing one another in pagan courts and reminds them their bodies, indwelt by the Holy Spirit, belong to God and should be honored, not used for sexual immorality."),
 ],
 "themes":["Loving church discipline aims at restoration, not mere punishment or gossip.","Because believers' bodies belong to God, sexual purity is a matter of worship, not merely personal preference."],
 "expositor":("macarthur","MacArthur has taught that church discipline in 1 Corinthians 5 is ultimately an act of love -- both protecting the church's witness and, ideally, shocking the unrepentant person toward the very repentance that restores them."),
 "reflect":"Is there an area of compromise you've been quietly tolerating in your own life the way the Corinthians tolerated sin in their midst?"},

{"day":50,"book":"1 Corinthians","ref":"1 Corinthians 7-9","title":"Marriage, Liberty, and Giving Up Rights for the Gospel",
 "chapters":[
   ("1 Cor 7","Paul answers the Corinthians' questions about marriage, celibacy, and divorce, affirming both singleness and marriage as legitimate callings depending on God's gifting to each person."),
   ("1 Cor 8","Paul addresses food sacrificed to idols, teaching that love for a weaker believer's conscience should limit the exercise of one's own theologically correct freedom."),
   ("1 Cor 9","Paul defends his right to financial support as an apostle, yet describes voluntarily forgoing that right so nothing hinders the gospel, and compares disciplined Christian living to an athlete training for a prize."),
 ],
 "themes":["Both singleness and marriage are legitimate, gift-based callings, not one superior to the other.","Christian freedom is rightly limited by love for others, not merely personal preference."],
 "expositor":("piper","Piper has often highlighted 1 Corinthians 9's picture of Paul disciplining himself 'like an athlete' as a model for gospel-motivated self-control -- not legalistic rule-keeping, but strategic sacrifice aimed at effective, unhindered ministry."),
 "reflect":"Is there a personal 'right' or preference you could voluntarily set aside for the sake of someone else's faith or a gospel opportunity?"},

{"day":51,"book":"1 Corinthians","ref":"1 Corinthians 10-12","title":"Warnings, Worship, and Spiritual Gifts",
 "chapters":[
   ("1 Cor 10","Paul warns against complacency by pointing to Israel's wilderness failures despite their privileges, and calls believers to flee idolatry while doing 'all for the glory of God.'"),
   ("1 Cor 11","Paul addresses order in worship gatherings and gives the earliest written account of the Lord's Supper, warning against approaching it carelessly or without self-examination."),
   ("1 Cor 12","Paul describes the church as one body with many different, Spirit-given gifts, none more essential than another, all needed for the body's health."),
 ],
 "themes":["Past privilege is no guarantee against present spiritual failure.","Every believer's spiritual gift matters and is needed within the body of Christ."],
 "expositor":("wiersbe","Wiersbe pointed out that Paul's body metaphor in 1 Corinthians 12 corrects two opposite errors at once -- feeling superior because of a prominent gift, and feeling worthless because of a seemingly minor one -- since every part is genuinely necessary."),
 "reflect":"Have you undervalued a gift or role God has given you simply because it seems less visible than someone else's?"},

{"day":52,"book":"1 Corinthians","ref":"1 Corinthians 13-14","title":"The Supremacy of Love, Order in Worship",
 "chapters":[
   ("1 Cor 13","Paul's celebrated 'love chapter' insists that without love, even impressive spiritual gifts, sacrifice, or knowledge amount to nothing -- love alone endures forever."),
   ("1 Cor 14","Paul gives practical guidelines for orderly, edifying use of spiritual gifts (especially prophecy and tongues) in corporate worship, prioritizing building up the whole church over individual display."),
 ],
 "themes":["Love is the necessary motive and measure behind every genuine spiritual gift.","Corporate worship should aim at building up the whole church, not showcasing individuals."],
 "expositor":("lewis","Lewis's discussion of charity in The Four Loves closely parallels 1 Corinthians 13, distinguishing love as a settled act of the will aimed at another's good from mere warm feeling -- exactly Paul's point that love 'is patient and kind' regardless of momentary emotion."),
 "reflect":"Read 1 Corinthians 13:4-7 slowly, replacing the word 'love' with your own name. Where does that expose a gap between your feelings and your will?"},

{"day":53,"book":"1 Corinthians","ref":"1 Corinthians 15-16","title":"The Resurrection Secures Everything",
 "chapters":[
   ("1 Cor 15","Paul defends the historical resurrection of Christ as the non-negotiable foundation of the entire faith, listing eyewitnesses, and describes believers' own future resurrection bodies."),
   ("1 Cor 16","Paul gives practical instructions about a collection for the suffering Jerusalem church and closes with warm, specific personal greetings."),
 ],
 "themes":["The resurrection is not optional decoration but the very foundation the whole gospel stands or falls on.","Practical generosity toward suffering believers elsewhere is a normal expression of gospel unity."],
 "expositor":("sproul","Sproul often stressed that 1 Corinthians 15 makes Christianity uniquely falsifiable and uniquely verifiable -- Paul stakes everything on a real, historical, witnessed event, meaning if the resurrection didn't happen, faith is worthless, but if it did, everything changes."),
 "reflect":"If the resurrection is truly the foundation Paul claims, how might genuinely believing that reshape your view of your own eventual death?"},

{"day":54,"book":"2 Corinthians","ref":"2 Corinthians 1-3","title":"Comfort in Suffering, Ministers of a New Covenant",
 "chapters":[
   ("2 Cor 1","Paul opens by describing God as 'the Father of compassion and the God of all comfort,' who comforts him in affliction so he, in turn, can comfort others in theirs."),
   ("2 Cor 2","Paul urges the Corinthians to forgive and restore a repentant church member who had previously caused grief, warning against excessive, unforgiving severity."),
   ("2 Cor 3","Paul contrasts the fading glory of the old covenant (symbolized by Moses' veiled face) with the surpassing, unveiled glory believers now experience through the Spirit."),
 ],
 "themes":["God's comfort in our suffering equips us to comfort others in theirs.","The new covenant offers a far greater, unveiled experience of God's glory than the old."],
 "expositor":("keller","Keller frequently taught that 2 Corinthians 1's principle -- comfort received becomes comfort given -- reframes personal suffering not as wasted pain but as future ministry material, since God rarely comforts us for our sake alone."),
 "reflect":"How might a past hardship you've walked through become a source of comfort for someone else facing something similar now?"},

{"day":55,"book":"2 Corinthians","ref":"2 Corinthians 4-6","title":"Treasure in Jars of Clay",
 "chapters":[
   ("2 Cor 4","Paul describes believers as fragile 'jars of clay' carrying the priceless treasure of the gospel, so that the surpassing power is clearly seen as God's, not their own."),
   ("2 Cor 5","Paul anticipates the believer's future resurrection body, describes living by faith not sight, and summarizes the gospel as God 'reconciling the world to himself' through Christ, making believers His ambassadors."),
   ("2 Cor 6","Paul appeals for the Corinthians' renewed affection toward him and warns against being unequally, compromisingly 'yoked' with unbelieving influences that would pull them from wholehearted devotion."),
 ],
 "themes":["Human weakness actually highlights, rather than hides, God's power at work.","Believers serve as Christ's ambassadors, representing His reconciling message to the world."],
 "expositor":("tozer","Tozer often reflected that the 'jars of clay' image in 2 Corinthians 4 frees believers from needing to appear impressive -- since the treasure, not the container, is what matters, weakness is no obstacle to being genuinely useful to God."),
 "reflect":"Where have you assumed your weakness disqualifies you from usefulness to God, rather than trusting it might actually display His power more clearly?"},

{"day":56,"book":"2 Corinthians","ref":"2 Corinthians 7-9","title":"Godly Sorrow and Grace-Filled Generosity",
 "chapters":[
   ("2 Cor 7","Paul rejoices that his earlier painful letter produced 'godly sorrow' leading to genuine repentance in the Corinthians, rather than mere worldly regret."),
   ("2 Cor 8","Paul commends the sacrificial generosity of the poor Macedonian churches as a model, urging the wealthier Corinthians to complete their promised gift for the Jerusalem believers."),
   ("2 Cor 9","Paul teaches principles of cheerful, deliberate generosity, promising that 'God loves a cheerful giver' and will supply generously to those who give generously."),
 ],
 "themes":["Godly sorrow leads to real change; mere regret over consequences does not.","Generosity should be cheerful, deliberate, and modeled on Christ's own self-giving, not reluctant obligation."],
 "expositor":("wiersbe","Wiersbe distinguished godly sorrow (which focuses on grieving sin against God and leads to change) from worldly sorrow (which focuses only on painful consequences and often leads nowhere), based directly on Paul's contrast in 2 Corinthians 7."),
 "reflect":"When you feel sorrow over a failure, is it typically more about the consequences you face, or genuine grief over having sinned against God?"},

{"day":57,"book":"2 Corinthians","ref":"2 Corinthians 10-11","title":"Paul Defends His Costly Apostleship",
 "chapters":[
   ("2 Cor 10","Paul insists his authority, though gentle in person, is real and Christ-given, and that spiritual battles are won with divinely powerful weapons, not worldly tactics."),
   ("2 Cor 11","Paul reluctantly lists his extraordinary sufferings for the gospel -- beatings, shipwrecks, danger, hunger -- to expose the hollow boasting of the 'super-apostles' who claimed superior credentials while doing far less."),
 ],
 "themes":["Genuine spiritual authority is measured by faithful sacrifice, not impressive self-promotion.","Suffering for the gospel, not avoiding it, marked authentic apostolic ministry."],
 "expositor":("begg","Alistair Begg has observed that Paul's reluctant 'boasting' in weakness and suffering in 2 Corinthians 11 deliberately mocks the culture's obsession with credentials, reframing true spiritual authority around faithfulness under hardship rather than polished self-promotion."),
 "reflect":"Are you tempted to measure spiritual credibility -- your own or others' -- more by outward polish than by faithful endurance through hardship?"},

{"day":58,"book":"2 Corinthians","ref":"2 Corinthians 12-13","title":"Strength Made Perfect in Weakness",
 "chapters":[
   ("2 Cor 12","Paul describes an unnamed 'thorn in the flesh' he pleaded three times to have removed, and God's answer -- 'my grace is sufficient for you, for my power is made perfect in weakness' -- becomes his settled conviction."),
   ("2 Cor 13","Paul closes with a final warning to examine whether they are truly 'in the faith,' and a benediction of grace, love, and fellowship that has become one of the most widely used blessings in Christian worship."),
 ],
 "themes":["God's grace is specifically sized to be sufficient for unresolved weakness, not just eventual healing.","Genuine self-examination of one's faith is a healthy, ongoing practice, not a sign of instability."],
 "expositor":("spurgeon","Spurgeon, who suffered from depression and chronic illness throughout his ministry, preached with unusual authority on 2 Corinthians 12:9, teaching that God gives grace sized exactly to today's trouble, not tomorrow's imagined one."),
 "reflect":"Is there a 'thorn' you've been asking God to remove? What might it look like to ask instead for grace sufficient for it, as Paul did?"},
]
